static int nfs_follow_referral ( struct fs_context * fc , const struct nfs4_fs_locations * locations ) { struct nfs_fs_context * ctx = nfs_fc2context ( fc ) ; int loc , error ; dprintk ( "%s: referral at %pd2\n" , __func__ , ctx -> clone_data . dentry ) ; error = nfs4_validate_fspath ( ctx -> clone_data . dentry , locations , ctx ) ; if ( error < 0 ) { return error ; } error = - ENOENT ; for ( loc = 0 ; loc < locations -> nlocations ; loc ++ ) { const struct nfs4_fs_location * location = & locations -> locations [ loc ] ; if ( location == NULL || location -> nservers <= 0 || location -> rootpath . ncomponents == 0 ) { continue ; } error = try_location ( fc , location ) ; if ( error == 0 ) { return 0 ; } } return error ; } 